#!/usr/bin/env node
// Differential test runner: compares /output/test2.mjs against the Python executable.
// Usage: node difftest.mjs [corpus.json ...]   (each file = JSON array of markdown source strings)
import { py, js } from './py.mjs';
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const files = process.argv.slice(2);
let cases = [];
if (files.length === 0) {
  const dir = '/workspace/harness/corpus';
  for (const f of readdirSync(dir).sort()) {
    if (f.endsWith('.json')) {
      for (const c of JSON.parse(readFileSync(join(dir, f), 'utf8'))) cases.push({ src: c, file: f });
    }
  }
} else {
  for (const f of files) for (const c of JSON.parse(readFileSync(f, 'utf8'))) cases.push({ src: c, file: f });
}

let pass = 0;
const fails = [];
for (const { src, file } of cases) {
  const a = py(src);
  const b = js(src);
  if (a.stdout === b.stdout && a.code === b.code) pass++;
  else fails.push({ file, src, expected: a.stdout, actual: b.stdout, ec: a.code, ac: b.code, stderr: b.stderr });
}

const showN = Number(process.env.SHOW || 12);
for (const f of fails.slice(0, showN)) {
  console.log('======== FAIL [' + f.file + '] input=' + JSON.stringify(f.src));
  console.log('-- expected(rc=' + f.ec + '): ' + JSON.stringify(f.expected));
  console.log('-- actual  (rc=' + f.ac + '): ' + JSON.stringify(f.actual));
  if (f.stderr) console.log('-- stderr: ' + f.stderr.split('\n').slice(0, 6).join('\n'));
}
console.log('\n==== ' + pass + '/' + cases.length + ' passed, ' + fails.length + ' failed');
process.exit(fails.length ? 1 : 0);

