const NB = " ";
const cases = [
  // unicode whitespace vs indentation
  NB + "   code",
  "   " + NB + "code",
  "    " + NB + "code",
  "    a" + NB,
  "    a" + NB + "\n    b",
  "> " + NB + "a",
  ">" + NB,
  "> a\n>" + NB + "\n> b",
  "    code",
  "　   code",
  "    a ",
  "> a ",
  "> a　",
  // \x0c form feed, \x0b vertical tab in strip
  ">",
  "> ",
  "    a ",
  "     code",
  // \x1c-\x1f
  ">",
  "    a",
  // deep nesting thresholds
  ">".repeat(100) + " x",
  ">".repeat(120) + " x",
  ">".repeat(150) + " x",
  ">".repeat(200) + " x",
  ">".repeat(300) + " x",
  // nested via spaced markers (each level costs indentation)
  "> ".repeat(50) + "x",
  "> ".repeat(80) + "x",
  // wide code indentation
  " ".repeat(40) + "x",
  " ".repeat(100) + "x",
  // many blank lines between code blocks
  "    a" + "\n".repeat(6) + "    b",
  "    a" + "\n".repeat(10) + "    b",
  // quote with many blank marker lines
  "> a" + "\n>".repeat(5) + "\n> b",
  // code block whose content is only spaces after detab
  "        \n    a",
  "    a\n        \n    b",
  // code with tab-only line
  "    a\n\t\n    b",
  "\ta\n\t\n\tb",
  // tab inside quote code
  ">     a\tb",
  ">\t\t\tx",
  // quote marker with tab immediately then text
  ">\tx\n>\ty",
  // CRLF at end
  "    code\r\n",
  "> quote\r\n",
  "    a\r\n\r\n    b",
  "> a\r\n\r\n> b",
  // lone CR
  "    a\r",
  // trailing whitespace-only lines with spaces
  "    a\n  \n    b",
  "    a\n\t\t\n    b",
  // paragraph then code where paragraph has trailing 2 spaces
  "para  \n\n    code",
  // code block with html entity-like and &nbsp
  "    &nbsp;&amp;",
  "    <>&\"'",
  // blockquote containing code with html
  ">     <b>&x</b>",
  // blockquote text with html chars
  "> a < b & c > d",
  "> \"q\" 'a'",
  // extremes
  ">",
  ">>",
  ">>>",
  "> >",
  ">  >",
  ">   >",
  ">    >",
  ">     >",
];
